public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Informs TDLib that a gift auction was closed by the user
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> CloseGiftAuctionAsync(long giftId = default)
    {

           using var activity =  StartCallActivity("CloseGiftAuctionAsync", typeof(CloseGiftAuction).FullName ?? "CloseGiftAuctionAsync");

           try
           {
             return client.CloseGiftAuctionAsync(giftId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
